@push('scripts')<script>$(function(){const tb=$('#production-return-lines tbody'),issue=$('#production-issue-select'),lineUrl='{{ route('wms.production.issue-returns.issue-line-options') }}';window.erpInitSelect2(issue,{ajax:{url:'{{ route('wms.production.issue-returns.issue-options') }}',delay:250,data:p=>({q:p.term||'',page:p.page||1}),processResults:d=>d}});function initLine(s){window.erpInitSelect2(s,{ajax:{url:lineUrl,delay:250,data:p=>({q:p.term||'',issue_document_id:issue.val()}),processResults:d=>d}});}function activate(){tb.find('select,input').prop('disabled',false);$('#add-production-return-line').prop('disabled',false);tb.find('.js-production-return-line').each(function(){initLine($(this));});}issue.on('select2:select',activate);@if($selectedIssue)activate();@endif $('#add-production-return-line').on('click',function(){const i=tb.find('tr').length,r=$('<tr><td><select class="form-select js-production-return-line" name="lines['+i+'][issue_line_id]" required><option value="">เลือกรายการ</option></select></td><td><input class="form-control text-end" type="number" name="lines['+i+'][quantity]" min="0.00000001" step="any" required></td><td><button type="button" class="btn btn-sm btn-app-danger js-production-return-remove" title="ลบรายการ"><i class="bx bx-trash"></i></button></td></tr>');tb.append(r);initLine(r.find('.js-production-return-line'));});tb.on('click','.js-production-return-remove',function(){if(tb.find('tr').length>1)$(this).closest('tr').remove();});window.erpAjaxForm({form:'#production-return-form',url:$('#production-return-form').attr('action'),method:'POST',redirect:true});});</script>@endpush
